/* Өгөгдөл серверийн SQLite санд хадгалагдана (server.py).
   Хуудас ачаалагдахад /api/all-аас бүх өгөгдлийг нэг дор татаж санах ойд (cache) хадгална,
   өөрчлөлтийг дарааллаар нь сервер рүү илгээнэ. Хуудасны код S79.ready-г хүлээж эхэлнэ. */
const S79={
  cache:{}, me:null, offline:false, q:Promise.resolve(),
  key:n=>'s79_cms_'+n,
  clone:v=>v==null?v:JSON.parse(JSON.stringify(v)),
  api(method,url,body){
    return fetch(url,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-S79':'1','X-S79-Since':String(S79.since||0)},body:body===undefined?undefined:JSON.stringify(body)})
      .then(async r=>{const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||('Серверийн алдаа '+r.status));return j});
  },
  load(){return S79.q.then(()=>S79.api('GET','/api/all')).then(j=>{S79.cache=j.data||{};S79.me=j.me||null;S79.since=j.now||0;S79.offline=false})},
  err(e){const m='Хадгалж чадсангүй: '+e.message;typeof toast==='function'?toast(m):alert(m)},
  raw(k,d){const v=S79.cache[k];return v==null?d:S79.clone(v)},
  // Нэвтэрсэн хэрэглэгч л сервер рүү бичнэ; зочны хувьд зөвхөн санах ойд үлдэнэ
  put(k,v,onDone){
    S79.cache[k]=S79.clone(v);
    if(!S79.me||S79.offline)return true;
    S79.q=S79.q.then(()=>S79.api('PUT','/api/data/'+encodeURIComponent(k),v)).then(r=>{onDone&&onDone(null,r)},e=>{S79.err(e);onDone&&onDone(e)});
    return true;
  },
  // Сайтын зочин бүртгэл, зурвас, зар, гомдол нэмэх
  append(k,item){return S79.api('POST','/api/append/'+encodeURIComponent(k),item).then(r=>{const l=S79.cache[k]||[];k==='s79_cms_ads'?l.unshift(r.item):l.push(r.item);S79.cache[k]=l;return r.item})},
  get(n){
    let v=S79.raw(S79.key(n),null);
    if(v==null)v=S79.clone(S79_DEFAULTS[n]);
    if(Array.isArray(v)){
      let fresh=false;
      v.forEach(x=>{if(x&&typeof x==='object'&&!x.id){x.id=Math.random().toString(36).slice(2,10);fresh=true}});
      if(fresh)S79.set(n,v); // id тогтвортой байхын тулд хадгална
    }
    else if(S79_DEFAULTS[n]&&typeof S79_DEFAULTS[n]==='object')v={...S79_DEFAULTS[n],...v};
    return v;
  },
  set(n,v,onDone){return S79.put(S79.key(n),v,onDone)},
  log(t,sec,user){const l=S79.raw('s79_cms_log',[]);l.unshift({t,sec,user,at:Date.now()});S79.put('s79_cms_log',l.slice(0,100))},
  img(v){if(!v)return'';if(String(v).startsWith('media:')){const m=(S79.cache[S79.key('media')]||[]).find(x=>x.id===v.slice(6));return m?m.src:''}return v},
  fmtDate:d=>d?String(d).replace(/-/g,'.'):'',
};
S79_DEFAULTS.teachers.forEach((t,i)=>t.o=i);
// Сервер ажиллахгүй (жишээ нь файлыг шууд нээсэн) үед анхны контентоор харуулна
S79.ready=S79.load().catch(e=>{S79.offline=true;console.warn('S79: сервертэй холбогдсонгүй, анхны өгөгдлөөр харуулж байна.',e)});
